css:
.print-format { font-family: Arial, sans-serif; font-size: 10pt; color: #000; }
.pst-title { text-align: center; font-size: 14pt; font-weight: bold; margin-bottom: 6px; }
.pst-table { width: 100%; border-collapse: collapse; }
.pst-table th, .pst-table td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; }
.pst-section-label { font-weight: bold; font-size: 9pt; }
.pst-right { text-align: right; }
.pst-bold { font-weight: bold; }
.pst-mono { font-family: 'Courier New', monospace; }
.pst-small { font-size: 8.5pt; }
.pst-no-border td { border: none; padding: 1px 2px; }
.pst-totals { font-weight: bold; }
.pst-footer { margin-top: 6px; }
